#[test]
fn every_test_file_is_compiled() {
    let chunks = [
        include_str!("all_1.rs"),
        include_str!("all_2.rs"),
        include_str!("all_3.rs"),
        include_str!("all_4.rs"),
    ];
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests");
    let mut bad = Vec::new();
    for entry in std::fs::read_dir(dir).expect("read tests/") {
        let name = entry
            .expect("dir entry")
            .file_name()
            .into_string()
            .expect("utf-8 name");
        if name.ends_with(".rs") && name != "all.rs" && !name.starts_with("all_") {
            let stem = &name[..name.len() - 3];
            let path_attr = format!("#[path = \"{name}\"]");
            let mod_decl = format!("\nmod {stem};");
            let pair = format!("{path_attr}{mod_decl}");
            let pair_hits: usize = chunks.iter().map(|c| c.matches(&pair).count()).sum();
            let path_hits: usize = chunks.iter().map(|c| c.matches(&path_attr).count()).sum();
            let mod_hits: usize = chunks.iter().map(|c| c.matches(&mod_decl).count()).sum();
            if pair_hits != 1 || path_hits != 1 || mod_hits != 1 {
                bad.push(name);
            }
        }
    }
    assert!(
        bad.is_empty(),
        "test files not compiled into exactly one tests/all_<k>.rs: {bad:?}; run python3 api/scripts/gen-test-binaries.py"
    );
}
